.studio-nav {
  font-family: system-ui, sans-serif;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 20px;
  border-radius: 10px;
  border: 1px solid #cbd5e1;
  background: #0f172a;
  color: #f8fafc;
}
.brand { font-weight: 800; font-size: 15px; letter-spacing: -0.02em; color: #38bdf8; }
.nav-links { display: flex; gap: 16px; }
.nav-links a { color: #e2e8f0; text-decoration: none; font-size: 13px; font-weight: 500; }
